package com.jgeted.sagadyssey.social.politics;

import net.minecraft.core.UUIDUtil;
import com.jgeted.sagadyssey.social.combat.NaturalConflictData;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
import java.util.UUID;
import static org.junit.jupiter.api.Assertions.*;
class NaturalCharterRecoveryTest {
 private static CompoundTag village(boolean wood){var t=new CompoundTag();t.putString("Dimension","minecraft:overworld");t.putString("Structure","sagadyssey:vilg_2");t.putLong("Start",wood?new net.minecraft.core.BlockPos(256,0,0).asLong():0L);t.putLong("Center",wood?new net.minecraft.core.BlockPos(256,0,0).asLong():0L);t.putLong("Origin",wood?new net.minecraft.core.BlockPos(256,0,0).asLong():0L);t.putString("Template",wood?"sagadyssey:vilg_2_wood_v2":"sagadyssey:vilg_2_farm_v2");t.putString("Rotation","NONE");return t;}
 @Test void interruptedConstructionKeepsItsIntentAndRequiresReview(){var root=new CompoundTag();root.putInt("Schema",1);var sites=new ListTag();var row=new CompoundTag();row.put("Village",village(false));var project=new CompoundTag();UUID id=UUID.randomUUID();project.store("Id", UUIDUtil.CODEC,id);project.store("ApprovedBy", UUIDUtil.CODEC,UUID.randomUUID());project.putString("Stage","BED");project.putBoolean("Submitting",true);project.putInt("Work",400);project.putString("PhysicalEvidence","original public material snapshot retained");row.put("Project",project);sites.add(row);root.put("Sites",sites);root.put("Decisions",new ListTag());var loaded=NaturalPolityData.load(root,null).sites().getFirst().getCompoundOrEmpty("Project");assertEquals("REVIEW",loaded.getStringOr("Stage", ""));assertEquals(id,loaded.read("Id", UUIDUtil.CODEC).orElseThrow());assertEquals(project.getStringOr("PhysicalEvidence", ""),loaded.getStringOr("PhysicalEvidence", ""));}
 @Test void interruptedPublicAllocationDoesNotBecomeASecondFreshDecision(){var root=new CompoundTag();root.putInt("Schema",1);root.put("Sites",new ListTag());var list=new ListTag();var decision=new CompoundTag();UUID id=UUID.randomUUID();decision.store("Id", UUIDUtil.CODEC,id);decision.putString("State","SUBMITTING");list.add(decision);root.put("Decisions",list);var loaded=NaturalPolityData.load(root,null).decisions();assertEquals(1,loaded.size());assertEquals(id,loaded.getFirst().read("Id", UUIDUtil.CODEC).orElseThrow());assertEquals("REVIEW",loaded.getFirst().getStringOr("State", ""));list.add(decision.copy());assertThrows(IllegalArgumentException.class,()->NaturalPolityData.load(root,null));}
 @Test void interruptedDisputeRationsKeepOriginalPeopleSitesAndCostEvidence(){var root=new CompoundTag();root.putInt("Schema",1);var list=new ListTag();var row=new CompoundTag();UUID id=UUID.randomUUID();row.store("Id", UUIDUtil.CODEC,id);row.put("A",village(false));row.put("B",village(true));row.putString("State","PREPARING");row.putInt("ConsumedCarrots",4);list.add(row);root.put("Disputes",list);var loaded=NaturalConflictData.load(root,null).disputes().getFirst();assertEquals("REVIEW",loaded.getStringOr("State", ""));assertEquals(4,loaded.getIntOr("ConsumedCarrots", 0));assertEquals(id,loaded.read("Id", UUIDUtil.CODEC).orElseThrow());assertEquals(row.getCompoundOrEmpty("A"),loaded.getCompoundOrEmpty("A"));}
}
